function print_image_uv_sampling_summary(check)
%PRINT_IMAGE_UV_SAMPLING_SUMMARY
%
% Print Cartesian image-grid / UV-support diagnostics generated by
% validate_image_uv_sampling.


requiredFields = { ...
    'status', ...
    'deltaL_mas', ...
    'deltaM_mas', ...
    'nL', ...
    'nM', ...
    'uNyq_Glambda', ...
    'vNyq_Glambda', ...
    'uMax_Glambda', ...
    'vMax_Glambda', ...
    'qU', ...
    'qV', ...
    'pixelsPerFringeU', ...
    'pixelsPerFringeV', ...
    'nLMinNyquist', ...
    'nMMinNyquist', ...
    'nLRecommended', ...
    'nMRecommended', ...
    'qRecommended'};


for k = 1:numel(requiredFields)

    if ~isfield(check, requiredFields{k})

        error([ ...
            'Sampling-check structure is missing field "%s".'], ...
            requiredFields{k});

    end

end


fprintf('\nImage-grid UV sampling check\n');

fprintf('  status                     = %s\n', ...
    check.status);

fprintf('  image grid                 = %d x %d\n', ...
    check.nL, ...
    check.nM);

fprintf('  delta l                    = %.6g mas\n', ...
    check.deltaL_mas);

fprintf('  delta m                    = %.6g mas\n', ...
    check.deltaM_mas);

fprintf('  u Nyquist                  = %.6g Glambda\n', ...
    check.uNyq_Glambda);

fprintf('  v Nyquist                  = %.6g Glambda\n', ...
    check.vNyq_Glambda);

fprintf('  max |u|                    = %.6g Glambda\n', ...
    check.uMax_Glambda);

fprintf('  max |v|                    = %.6g Glambda\n', ...
    check.vMax_Glambda);

fprintf('  q_u = max|u|/u_Nyq        = %.6f\n', ...
    check.qU);

fprintf('  q_v = max|v|/v_Nyq        = %.6f\n', ...
    check.qV);

fprintf('  pixels per finest u fringe = %.4f\n', ...
    check.pixelsPerFringeU);

fprintf('  pixels per finest v fringe = %.4f\n', ...
    check.pixelsPerFringeV);

fprintf('  minimum Nyquist grid       = %d x %d\n', ...
    check.nLMinNyquist, ...
    check.nMMinNyquist);

fprintf('  recommended q <= %.2f grid = %d x %d\n', ...
    check.qRecommended, ...
    check.nLRecommended, ...
    check.nMRecommended);

end